package com.sprint.mission.discodeit.entity;

import jakarta.persistence.*;
import lombok.Getter;
import org.springframework.data.annotation.CreatedDate;
import org.springframework.data.jpa.domain.support.AuditingEntityListener;

import java.time.Instant;
import java.util.UUID;

@Getter
@MappedSuperclass
@EntityListeners(AuditingEntityListener.class)
public abstract class BaseEntity {

    // JPA에게 @Id 애너테이션이 붙은 필드를 기본 키라고 알려줍니다.
    @Id
    // GenerationType.IDENTITY는 DB의 IDENTITY 컬럼에 값 생성을 맡깁니다.
    // schema.sql 파일에 `id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY`
    // 위와 같은 것을 명시해주어야합니다.
    // GenerationType.UUID는 Hibernates가 INSERT 전에, UUID를 자동으로 할당합니다.
    // @Id, @GeneratedValue(strategy = GenerationType.UUID)를 사용한다면,
    // User 생성자에서, this.id = UUID.randomUUID(); 는 더 이상 사용하지 않아도됩니다.
    @GeneratedValue(strategy = GenerationType.UUID)
    UUID id;

    // 객체가 처음 영속화 될 때, 현재 시각을 필드에 할당합니다.
    @CreatedDate
    Instant createdAt;
}
